import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import 'package:rasikh/data/divisions.dart';
import 'package:rasikh/data/mushaf.dart';

/// The muṣḥaf's divisions (lib/data/divisions_data.dart, generated by
/// tool/gen_divisions.py) agree with the juzʼ table and the printed text.
void main() {
  final meta = (jsonDecode(File('assets/quran/meta.json').readAsStringSync())
          as List)
      .cast<Map<String, dynamic>>();
  final ayahs = [for (final m in meta) m['ayahs'] as int];
  final text = (jsonDecode(
          File('assets/quran/mushaf_u_text.json').readAsStringSync()) as List)
      .cast<String>();
  final indopak = (jsonDecode(
          File('assets/quran/mushaf_i_text.json').readAsStringSync()) as List)
      .cast<String>();
  (int, int) sa(int g) {
    var s = 0;
    while (g >= ayahs[s]) {
      g -= ayahs[s];
      s++;
    }
    return (s + 1, g + 1);
  }

  test('counts: 240 quarters, 60 aḥzāb, 7 manāzil, 558 rukūʿ', () {
    expect(rubStarts, hasLength(240));
    expect(divisionCount(Division.hizb), 60);
    expect(manzilStarts, hasLength(7));
    expect(rukuStarts, hasLength(558));
    for (final starts in [rubStarts, manzilStarts, rukuStarts]) {
      for (var i = 1; i < starts.length; i++) {
        final (a, b) = (starts[i - 1], starts[i]);
        expect(a.$1 < b.$1 || (a.$1 == b.$1 && a.$2 < b.$2), isTrue,
            reason: 'out of order at $b');
      }
    }
  });

  test('every juzʼ starts on its eighth quarter', () {
    for (var j = 1; j <= 30; j++) {
      final (s, a) = rubStarts[(j - 1) * 8];
      expect(MushafRepo.juzOfAyah(s, a), j, reason: 'quarter ${(j - 1) * 8 + 1}');
      expect(firstAyahOf(Division.juz, j), (s, a));
      if (j > 1) {
        final (ps, pa) = a > 1 ? (s, a - 1) : (s - 1, ayahs[s - 2]);
        expect(MushafRepo.juzOfAyah(ps, pa), j - 1);
      }
    }
  });

  test('every printed ۞ starts a quarter; the rest open a sūrah', () {
    final marked = <(int, int)>{
      for (var g = 0; g < text.length; g++)
        if (text[g].contains('۞')) sa(g),
    };
    expect(marked, hasLength(199));
    expect(rubStarts.toSet().containsAll(marked), isTrue);
    for (final q in rubStarts.toSet().difference(marked)) {
      expect(q.$2, 1, reason: '$q has no ۞ and is not a sūrah opening');
    }
  });

  test('a rukūʿ ends at every ࣖ the Indo-Pak text prints', () {
    final ends = <(int, int)>{
      for (var g = 0; g < indopak.length; g++)
        if (indopak[g].contains('ࣖ')) sa(g),
    };
    for (var i = 1; i < rukuStarts.length; i++) {
      final (s, a) = rukuStarts[i];
      final prev = a > 1 ? (s, a - 1) : (s - 1, ayahs[s - 2]);
      expect(ends.contains(prev), isTrue, reason: 'rukūʿ $i at ($s, $a)');
    }
  });

  test('lookups', () {
    expect(rubOf(1, 1), 1);
    expect(rubOf(2, 25), 1);
    expect(rubOf(2, 26), 2);
    expect(rubOf(15, 49), rubOf(15, 50)); // the text's ۞ is at 15:49
    expect(rubOf(15, 48) + 1, rubOf(15, 49));
    expect(hizbOf(2, 74), 1);
    expect(hizbOf(2, 75), 2);
    expect(hizbOf(114, 6), 60);
    expect(rubOf(114, 6), 240);
    expect(manzilOf(4, 176), 1);
    expect(manzilOf(5, 1), 2);
    expect(manzilOf(114, 6), 7);
    expect(rukuOf(1, 7), 1);
    expect(rukuOf(2, 1), 2);
    expect(rukuOf(114, 6), 558);
    for (final d in Division.values.where((d) => d != Division.page)) {
      for (var n = 1; n <= divisionCount(d); n++) {
        final (s, a) = firstAyahOf(d, n);
        expect(divisionOf(d, s, a), n, reason: '$d $n');
      }
    }
  });
}
